import os
for r,ds,fs in os.walk('studies'):
 for f in fs: print(r,f)

import gzip,glob,csv
for f in sorted(glob.glob('studies/data/raw/*series*')):
 print('\nFILE',f)
 with gzip.open(f,'rt') as x:
  for l in x:
   if l.startswith(('!Sample_title','!Sample_geo_accession','!Sample_source_name','!Sample_characteristics')):
    a=next(csv.reader([l],delimiter='\t'));print(a[0],len(a)-1, a[1:])

import gzip,glob,csv,collections
for f in sorted(glob.glob('studies/data/raw/*series*')):
 print('\nFILE',f)
 with gzip.open(f,'rt') as x:
  for l in x:
   if l.startswith(('!Sample_title','!Sample_source_name','!Sample_characteristics')):
    a=next(csv.reader([l],delimiter='\t')); print(a[0],dict(collections.Counter(a[1:]))) if not ('paper_2' in f and not l.startswith('!Sample_characteristics')) else None

